window.PACK={"book":{"id":"diwan-nabigha","title":"ديوان النابغة الذبياني","type":"diwan","author":"النابغة الذبياني (ت نحو ١٨ ق.هـ)","source":"الموسوعة الشعرية / المكتبة الشاملة عبر مشروع OpenITI","optional":true,"era":"jahili","packVersion":"9ec09ae08331"},"items":[{"id":"diwan-nabigha:1","bookId":"diwan-nabigha","type":"poem","seq":1,"chapter":"البحر: طويل","title":"كليني لهم ، يا أميمة ، ناصب ،","page":"","text":"كليني لهم ، يا أميمة ، ناصب ، … وليل أقاسيه ، بطيء الكواكب\nتطاول حتى قلت ليس بمنقض ، … وليس الذي يرعى النجوم بآنب\nوصدر أراح الليل عازب همه ، … تضاعف فيه الحزن من كل جانب\nعلي لعمرو نعمة ، بعد نعمة … لوالده ، ليست بذات عقارب\nحلفت يمينا غير ذي مثنوية ، … ولا علم ، إلا حسن ظن بصاحب\nلئن كان للقبرين : قبر بجلق ، … وقبر بصيداء ، الذي عند حارب\nوللحارث الجفني ، سيد قومه ، … ليلتمسن بالجيش دار المحارب\nوثقت له النصر ، إذ قيل قد غزت … كتائب من غسان ، غير أشائب\nبنو عمه دنيا ، وعمرو بن عامر ، … أولئك قوم ، بأسهم غير كاذب\nإذا ما غزوا بالجيش ، حلق فوقهم … عصائب طير ، تهتدي بعصائب\nيصاحبنهم ، حتى يغرن مغارهم … من الضاريات ، بالدماء ، الدوارب\nتراهن خلف القوم خزرا عيونها ، … جلوس الشيوخ في ثياب المرانب\nجوانح ، قد أيقن أن قبيله ، … إذا ما التقى الجمعان ، أول غالب\nلهن عليهم عادة قد عرفنها ، … إذا عرض الخطي فوق الكواثب\nعلى عارفات للطعان ، عوابس ، … بهن كلوم بين دام وجالب\nإذا استنزلوا عنهن للطعن أرقلوا ، … إلى الموت ، إرقال الجمال المصاعب\nفهم يتساقون المنية بينهم ، … بأيديهم بيض ، رقا المضارب\nيطير فضاضا بينها كل قونس ، … ويتبعها منهم فراش الحواجب\nولا عيب فيهم غير أن سيوفهم ، … بهن فلول من قراع الكتائب\nتورثن من أزمان يوم حليمة ، … إلى اليوم قد جربن كل التجارب\nتقد السلوقي المضاعف نسجه ، … وتوقد بالصفاح نار الحباحب\nبضرب يزيل الهام عن سكناته ، … وطعن كإيزاغ المخاض الضوارب\nلهم شيمة ، لم يعطها الله غيرهم ، … من الجود ، والأحلام غير عوازب\nمحلتهم ذات الإله ، ودينهم ، … قويم ، فما يرجون غير العواقب\nرقاق النعال ، طيب حجزاتهم ، … يحيون بالريحان يوم السباسب"},{"id":"diwan-nabigha:2","bookId":"diwan-nabigha","type":"poem","seq":2,"chapter":"البحر: بسيط تام","title":"إني كأني ، لدى النعمان خبره","page":"","text":"إني كأني ، لدى النعمان خبره … بعض الأود حديثا ، غير مكذوب\nبأن حصنا وحيا من بني أسد ، … قاموا ، فقالوا : حمانا غير مقروب\nضلت حلومهم عنهم ، وغرهم … سن المعيدي غي رعي وتغريب\nقاد الجياد من الجولان ، قائظة ، … من بين منعلة تزجى ، ومجنوب\nحتى استغاثت بأهل الملح ، ما طمعت ، … في منزل ، طعم نوم غير تأويب\nينضحن نضح المزاد الوفر أتأقها … شد الرواة بماء ، غير مشروب\nقب الأياطل تردي في أعنتها ، … كالخاضبات من الزعر الظنابيب\nشعت ، عليها مساعير لحربهم ، … شم العرانين من مرد ومن شيب\nوما بحصن نعاس ، إذ تؤرقه … أصوات حي ، علي الأمرار ، محروب\nظلت أقاطيع أنعام مؤبلة ، … لدى صليب ، على الزوراء ، منصوب\nفإذا وقيت ، بحمد الله ، شرتها ، … فانجي ، فزار ، إلى الأطواد ، فاللوب\nولا تلاقي كما لاقت بنو أسد ، … فقد أصابتهم منها بشؤبوب\nلم يبق غير طريد غير منفلت ، … وموثق في حبال القد ، مسلوب\nأو حرة كمهاة الرمل قد كبلت … فوق المعاصم منها ، والعراقيب\nتدعو قعينا وقد عض الحديد بها ، … عض الثقاف على صم الأنابيب\nمستشعرين قد الفوا ، في ديارهم ، … دعاء سوع ، ودعمي ، وأيوب"},{"id":"diwan-nabigha:3","bookId":"diwan-nabigha","type":"poem","seq":3,"chapter":"البحر: طويل","title":"أتاني أبيت اللعن أنك لمتني ،","page":"","text":"أتاني أبيت اللعن أنك لمتني ، … وتلك التي أهتم منها وأنصب\nفبت كأن العائدات فرشنني … هراسا ، به يعلى فراشي ويقشب\nحلفت ، فلم أترك لنفسك ريبة ، … وليس وراء الله للمرء مذهب\nلئن كنت قد بلغت عني خيانة ، … لمبلغك الواشي أغش وأكذب\nولكنني كنت امرأ لي جانب … من الأرض ، فيه مستراد ومذهب\nملوك وإخوان ، إذا ما أتيتهم ، … أحكم في أموالهم ، وأقرب\nكفعلك في قوم أراك اصطنعتهم ، … فلم ترهم ، في شكر ذلك ، أذنبوا\nفلا تتركني بالوعيد ، كأنني … إلى الناس مطلي به القار ، أجرب\nألم تر أن الله أعطاك سورة ، … ترى كل ملك ، دونها ، يتذبذب\nفإنك شمس ، والملوك كواكب ، … إذا طلعت لم يبد منهن كوكب\nولست بمستبق أخا ، لا تلمه … على شعث ، أي الرجال المهذب ؟\nفإن أك مظلوما ؛ فعبد ظلمته ؛ … وإن تك ذا عتبى ؛ فمثلك يعتب"},{"id":"diwan-nabigha:4","bookId":"diwan-nabigha","type":"poem","seq":4,"chapter":"البحر: وافر تام","title":"فإن يك عامر قد قال جهلا ،","page":"","text":"فإن يك عامر قد قال جهلا ، … فإن مظنة الجهل الشباب\nفكن كأبيك ، أو كأبي براء ، … توافقك الحكومة والصواب\nولا تذهب . بحلمك ، طاميات … من الخيلاء ، ليس لهن باب\nفإنك سوف تحلم ، أو تناهى ، … إذا ما شبت ، أو شاب الغراب\nفإن تكن الفوارس ، يوم حسي ، … أصابوا ، من لقائك ، ما أصابوا\nفما إن كان من نسب بعيد ، … ولكن أدركوك ، وهم غضاب\nفوارس ، من منولة ، غير ميل ، … ومرة ، فوق جمعهم العقاب"},{"id":"diwan-nabigha:5","bookId":"diwan-nabigha","type":"poem","seq":5,"chapter":"البحر: بسيط تام","title":"من يطلب الدهر تدركه مخالبه ،","page":"","text":"من يطلب الدهر تدركه مخالبه ، … والدهر بالوتر ناج ، غير مطلوب\nما من أناس ذوي مجد ومكرمة ، … إلا يشد عليهم شدة الذيب\nحتى يبيد ، على عمد ، سراتهم ، … بالنافذات من النبل المصاييب\nإني وجدت سهام الموت معرضة … بكل حتف ، من الآجال ، مكتوب"},{"id":"diwan-nabigha:6","bookId":"diwan-nabigha","type":"poem","seq":6,"chapter":"البحر: طويل","title":"أرسما جديدا من سعاد تجنب ؟","page":"","text":"أرسما جديدا من سعاد تجنب ؟ … عفت روضة الأجداد منها ، فيثقب\nعفا آية ريح الجنوب مع الصبا ، … وأسحم دان ، مزنه متصوب"},{"id":"diwan-nabigha:7","bookId":"diwan-nabigha","type":"poem","seq":7,"chapter":"البحر: طويل","title":"كأن قتودي ، والنسوع جرى بها","page":"","text":"كأن قتودي ، والنسوع جرى بها … مصك ، يباري الجون ، جأب معقرب\nرعى الروض حتى نشت الغدر والتوت … برجلاتها ، قيعان شرج وأيهب"},{"id":"diwan-nabigha:8","bookId":"diwan-nabigha","type":"poem","seq":8,"chapter":"البحر: بسيط تام","title":"حذاء مدبرة ، سكاء مقبلة ،","page":"","text":"حذاء مدبرة ، سكاء مقبلة ، … للماء ، في النحر منها ، نوطة عجب\nتدعو القطا ، وبها تدعى ، إذا نسبت … يا حسنها ، حين تدعوها ، فتنتسب"},{"id":"diwan-nabigha:9","bookId":"diwan-nabigha","type":"poem","seq":9,"chapter":"البحر: طويل","title":"لعمري ، لنعم المرء من آل ضجعم ،","page":"","text":"لعمري ، لنعم المرء من آل ضجعم ، … تزور ببصرى ، أو ببرقة هارب\nفتى ، لم تلده بنت أم قريبة ، … فيضوي ، وقد يضوى رديد الأقارب"},{"id":"diwan-nabigha:10","bookId":"diwan-nabigha","type":"poem","seq":10,"chapter":"البحر: وافر تام","title":"وما حاولتما بقياد خيل ،","page":"","text":"وما حاولتما بقياد خيل ، … يصول الورد فيها والكميت\nإلى ذبيان ، حتى صبحتهم ، … ودونهم الربائع والخبيت"},{"id":"diwan-nabigha:11","bookId":"diwan-nabigha","type":"poem","seq":11,"chapter":"البحر: وافر تام","title":"كأن الظعن ، حين طفون ظهرا ، ،","page":"","text":"كأن الظعن ، حين طفون ظهرا ، ، … سفين\nقفا ، فتبينا أعريتنات … يوخي الحي ، أم أموا لباحا\nكأن ، على الحدوج ، نعاج رمل ، … زهاها الذعر ، أو سمعت صياحا"},{"id":"diwan-nabigha:12","bookId":"diwan-nabigha","type":"poem","seq":12,"chapter":"البحر: كامل تام","title":"واستبق ودك للصديق ، ولا تكن","page":"","text":"واستبق ودك للصديق ، ولا تكن … قتبا يعض بغارب ، ملحاحا\nفالرفق يمن ، والأناة سعادة ، … فتأن في رفق تنال نجاحا\nواليأس مما فات يعقب راحة ، … ولرب مطعمة تعود ذباحا\nيعد ابن جفنة وابن هاتك عرشه ، … والحارثين ، بأن يزيد فلاحا\nولقد رأى أن الذين هو غالهم ، … قد غال حمير قيلها الصباحا\nوالتبعين ، وذا نؤاس ، غدوة … وعلا أذينة ، سالب الأرواحا"},{"id":"diwan-nabigha:13","bookId":"diwan-nabigha","type":"poem","seq":13,"chapter":"البحر: طويل","title":"يقولون : حصن ، ثم تأبى نفوسهم ؛","page":"","text":"يقولون : حصن ، ثم تأبى نفوسهم ؛ … وكيف بحصن ، والجبال جموح\nولم تلفظ الموتى القبور ، ولم تزل … نجوم السماء ، والأديم صحيح"},{"id":"diwan-nabigha:14","bookId":"diwan-nabigha","type":"poem","seq":14,"chapter":"البحر: بسيط تام","title":"يا دار مية بالعلياء ، فالسند ،","page":"","text":"يا دار مية بالعلياء ، فالسند ، … أقوت ، وطال عليها سالف الأبد\nوقفت فيها أصيلانا أسائلها ، … عيت جوابا ، وما بالربع من أحد\nإلا الأواري لأيا ما أبينها ، … والنؤي كالحوض بالمظلومة الجلد\nردت عليه أقاصيه ، ولبده … ضرب الوليدة بالمسحاة في الثأد\nخلت سبيل أتي كان يحبسه ، … ورفعته إلى السجفين ، فالنضد\nأمست خلاء ، وأمسى أهلها احتملوا … أخننى عليها الذي أخنى على لبد\nفعد عما ترى ، إذ لا ارتجاع له ، … وانم القتود على عيرانة أجد\nمقذوفة بدخيس النحض ، بازلها … له صريف القعو بالمسد\nكأن رحلي ، وقد زال النهار بنا ، … يوم الجليل ، على مستأنس وحد\nمن وحش وجرة ، موشي أكارعه ، … طاوي المصير ، كسيف الصيقل الفرد\nسرت عليه ، من الجوزاء ، سارية ، … تزجي الشمال عليه جامد البرد\nفارتاع من صوت كلاب ، فبات له … طوع الشوامت من خوف ومن صرد\nفبثهن عليه ، واستمر به … صمع الكعوب بريئات من الحرد\nوكان ضمران منه حيث يوزعه ، … طعن المعارك عند المحجر النجد\nشك الفريصة بالمدرى ، فأنفذها ، … طعن المبيطر ، إذ يشفي من العضد\nكأنه ، خارجا من جنب صفحته ، … سفود شرب نسوه عند مفتأد\nفظل يعجم أعلى الروق ، منقبضا ، … في حالك اللون صدق ، غير ذي أود\nلما رأى واشق إقعاص صاحبه ، … ولا سبيل إلى عقل ، ولا قود\nقالت له النفس : إني لا أرى طمعا ، … وإن مولاك لم يسلم ، ولم يصد\nفتلك تبلغني النعمان ، إن له … فضلا على الناس في الأدنى ، وفي البعد\nولا أرى فاعلا ، في الناس ، يشبهه ، … ولا أحاشي ، من الأقوام ، من أحد\nإلا سليمان ، إذ قال الإله له : … قم في البرية ، فاحددها عن الفند\nوخيس الجن ! إني قد أذنت لهم … يبنون تدمر بالصفاح والعمد\nفمن أطاعك ، فانفعه بطاعته ، … كما أطاعك ، وادلله على الرشد\nومن عصاك ، فعاقبه معاقبة … تنهى الظلوم ، ولا تقعد على ضمد\nإلا لمثلك ، أو من أنت سابقه … سبق الجواد ، إذا استولى على الأمد\nأعطى لفارهة ، حلو توابعها ، … من المواهب لا تعطى على نكد\nالواهب المائة المعكاء ، زينها … سعدان توضح في أوبارها اللبد\nوالأدم قد خيست ، فتلا مرافقها … مشدودة برحال الحيرة الجدد\nوالراكضات ذيول الريط ، فانقها … برد الهواجر ، كالغزلان بالجرد\nوالخيل تمزغ غربا في أعنتها ، … كالطير تنجو من الشؤبوب ذي البرد\nاحكم كحكم فتاة الحي ، إذ نظرت … إلى حمام شراع ، وارد الثمد\nيحفه جانبا نيق ، وتتبعه … مثل الزجاجة ، لم تكحل من الرمد\nقالت : ألا ليتما هذا الحمام لنا … إلى حمامتنا ونصفه ، فقد\nفحسبوه ، فألقوه ، كما حسبت ، … تسعا وتسعين لم تنقص ولم تزد\nفكملت مائة فيها حمامتها ، … وأسرعت حسبة في ذلك العدد\nفلا لعمر الذي مسحت كعبته ، … وما هريق ، على الأنصاب ، من جسد\nوالمؤمن العائذات الطير ، تمسحها … ركبان مكة بين الغيل والسعد\nما قلت من سيء مما أتيت به ، … إذا فلا رفعت سوطي إلي يدي\nإلا مقالة أقوام شقيت بها ، … كانت مقالتهم قرعا على الكبد\nغذا فعاقبني ربي معاقبة ، … قرت بها عين من يأتيك بالفند\nأنبئت أن أبا قابوس أوعدني ، … ولا قرار على زأر من الأسد\nمهلا ، فداء لك الأقوام كلهم ، … وما أثمر من مال ومن ولد\nلا تقذفني بركن لا كفاء له ، … وإن تأثفك الأعداء بالرفد\nفما الفرات إذا هب الرياح له ، … ترمي أواذيه العبرين بالزبد\nيمده كل واد مترع ، لجب ، … فيه ركام من الينبوت والحضد\nيظل ، من خوفه ، الملاح معتصما … بالخيزرانة ، بعد الأين والنجد\nيوما ، بأجود منه سيب نافلة ، … ولا يحول عطاء اليوم دون غد\nهذا الثناء ، فإن تسمع به حسنا ، … فلم أعرض ، أبيت اللعن ، بالصفد\nها إن ذي عذرة إلا تكن نفعت ، … فإن صاحبها مشارك النكد"},{"id":"diwan-nabigha:15","bookId":"diwan-nabigha","type":"poem","seq":15,"chapter":"قصائد","title":"أمن آل مية رائح ، أو مغتد ،","page":"","text":"أمن آل مية رائح ، أو مغتد ، … عجلان ، ذا زاد ، وغير مزود\nأفد الترحل ، غير أن ركابنا … لما تزل برحالنا ، وكأن قد\nزعم البوارح أن رحلتنا غدا ، … وبذاك خبرنا الغداف الأسود\nلا مرحبا بغد ، ولا أهلا به ، … إن كان تفريق الأحبة في غد\nحان الرحيل ، ولم تودع مهددا ، … والصبح والإمساء منها موعدي\nفي إثر غانية رمتك بسهمها ، … فأصاب قلبك ، غير أن لم تقصد\nغنيت بذلك ، غذ هم لك جيرة ، … منها بعطف رسالة وتودد\nولقد أصابت قلبه من حبها ، … عن ظهر مرنان ، بسهم مصرد\nنظرت بمقلة شادن متربب … أحوى ، أحم المقلتين ، مقلد\nوالنظم في سلك يزين نحرها ، … ذهب توقد ، كالشهاب الموقد\nصفراء كالسيراء ، أكمل خلقها … كالغصن ، في غلوائه ، المتأود\nوالبطن ذو عكن ، لطيف طيه ، … والإتب تنفجه بثدي مقعد\nمحطوطة المتنين ، غير مفاضة ، … ريا الروادف ، بضة المتجرد\nقامت تراءى بين سجفي كلة ، … كالشمس يوم طلوعها بالأسعد\nأو درة صدفية غواصها … بهج متى يرها يهل ويسجد\nأو دمية من مرمر ، مرفوعة ، … بنيت بآجر ، تشاد ، وقرمد\nسقط النصيف ، ولم ترد إسقاطه ، … فتناولته ، واتقنا باليد\nبمخضب رخص ، كأن بنانه … عنم ، يكاد من اللطافة يعقد\nنظرت إليك بحاجة لم تقضها ، … نظر السقيم إلى وجوه العود\nتجلو بقادمتي حمامة أيكة ، … بردا أسف لثاته بالإثمد\nكالأقحوان ، غداة غب سمائه ، … جفت أعاليه ، وأسفله ندي\nزعم الهمام بأن فاها بارد ، … عذب مقبله ، شهي المورد\nزعم الهمام ، ولم أذقه ، أنه … عذب ، غذا ما ذقته قلت : ازدد\nزعم الهمام ، ولم أذقه ، أنه … يشفى ، بريا ريقها ، العطش الصدي\nأخذ العذارى عقدها ، فنظمنه ، … من لؤلؤ متتابع ، متسرد\nلو أنها عرضت لأشمط راهب ، … عبد الإله ، صرورة ، متعبد\nلرنا لبهجتها ، وحسن حديثها ، … ولخاله رشدا وإن لم يرشد\nبتكلم ، لو تستطيع سماعه ، … لدنت له أروى الهضاب الصخد\nوبفاحم رجل ، أثيث نيته ، … كالكرم مال على الدعام المسند\nفإذا لمست لمست أجثم جاثما ، … متحيزا بمكانه ، ملء اليد\nوإذا طعنت طعنت في مستهدف ، … رابي المجسة ، بالعبير مقرمد\nوغذا نزعت نزعت عن مستحصف … نزع الحزور بالرشاء المحصد\nوغذا يعض تشده أعضاؤه ، … عض الكبير من الرجال الأدرد\nويكاد ينزع جلد من يصلى به … بلوافح ، مثل السعير الموقد\nلا وارد منها يحور لمصدر … عنها ، ولا صدر يحور لمورد"},{"id":"diwan-nabigha:16","bookId":"diwan-nabigha","type":"poem","seq":16,"chapter":"البحر: طويل","title":"اهاجك ، من سعداك ، مغنى المعاهد","page":"","text":"اهاجك ، من سعداك ، مغنى المعاهد … بروضة نعمي ، فذات الأساود\nتعاورها الأرواح ينسفن تربها ، … وكل مثلث ذي أهاضيب ، راعد\nبها كل ذيال وخنساء ترعوي … إلى كل رجاف ، من الرمل ، فارد\nعهدت بها سعدي غريرة … عروب ، تهادى في جوار خرائد\nلعمري ، لنعم الحي صبح سر بنا … وأبياتنا ، يوما ، بذات المراود\nيقودهم النعمان منه بمصحف ، … وكيد يغم الخارجي ، مناجد\nوشيمة لا وان ، ولا واهن القوى ، … وجد ، إذا خاب المفيدون ، صاعد\nفآب بأبكار وعون عقائل ، … أوانس يحميها امرؤ غير زاهد\nيخططن بالعيدان في كل مقعد ، … ويخبأن رمان الثدي النواهد\nويضربن بالأيدي وراء براغز ، … حسان الوجوه ، كالظباء العواقد\nغرائر لم يلقين بأساء قبلها ، … لدى ابن الجلاح ، ما يثقن بوافد\nأصاب بني غيظ ، فأصحوا عباده ، … وجللها نعمى على غير واحد\nفلا بد من عوجاء تهوي براكب ، … إلى ابن الجلاح ، سيرها الليل قاصد\nتخب إلى النعمان ، حتى تناله ، … فدى لك من رب طريفي ، وتالدي\nفسكنت نفسي ، بعدما طار روحها ، … وألبستني نعمى ، ولست بشاهد\nوكنت امرأ لا أمدح الدهر سوقة ، … فلست ، على خير أتاك ، بحاسد\nسبقت الرجال الباهشين إلى العلى ، … كسبق الجواد اصطاد قبل الطوارد\nعلوت معدا نائلا ونكاية ، … فأنت ، لغيث الحمد ، أول رائد"},{"id":"diwan-nabigha:17","bookId":"diwan-nabigha","type":"poem","seq":17,"chapter":"البحر: طويل","title":"أبقيت للعبسي فضلا ونعمة ،","page":"","text":"أبقيت للعبسي فضلا ونعمة ، … ومحمدة من باقيات المحامد\nحباء شقيق فوق أعظم قبره ، … وما كان يحبى قبله قبر وافد\nأتى أهله منه حباء ونعمة ؛ … ورب امرىء يسعى لآخر قاعد"},{"id":"diwan-nabigha:18","bookId":"diwan-nabigha","type":"poem","seq":18,"chapter":"البحر: كامل تام","title":"يا عام ! لم أعرفك تنكر سنة ،","page":"","text":"يا عام ! لم أعرفك تنكر سنة ، … بعد الذين تتابعوا بالمرصد\nلو عاينتك كماتنا بطوالة ، … بالحزورية ، أو بلابة ضرغد\nلثويت في قد ، هنالك ، موثقا … في القوم ، أو لثويت غير موسد"},{"id":"diwan-nabigha:19","bookId":"diwan-nabigha","type":"poem","seq":19,"chapter":"البحر: بسيط تام","title":"عوجوا ، فحيوا لنعم دمنة الدار ،","page":"","text":"عوجوا ، فحيوا لنعم دمنة الدار ، … ماذا تحيون من نؤي وأحجار ؟\nأقوى ، وأقفر من نعم ، وغيره … هوج الرياح بها والترب ، موار\nوقفت فيها ، سراة اليوم ، أسألها … عن آل نعم ، أمونا ، عبر أسفار\nفاستعجمت دار نعم ، ما تكلمنا ، … والدار ، لو كلمتنا ، ذات أخبار\nفما وجدت بها شيئا ألوذ به ، … إلا الثمام وإلا موقد النار\nوقد أراني ونعما لاهيين بها ، … والدهر والعيش لم يهمم بإمرار\nأيام تخبرني نعم وأخبرها ، … ما أكتم الناس من حاجي وأسراري\nلولا حبائل من نعم علقت بها ، … لأقصر القلب عنها أي إقصار\nفإن أفاق ، لقد طالت عمايته ؛ … والمرء يخلق طورا بعد أطوار\nنبئت نعما ، على الهجران ، عاتبة ؛ … سقيا ورعيا لذاك العاتب الزاري\nرأيت نعما وأصحابي على عجل ، … والعيس ، للبين ، قد شدت بأكوار\nفريع قلبي ، وكانت نظرة عرضت … حينا ، وتوفيق أقدار لأقدار\nبيضاء كالشمس وافت يوم أسعدها ، … لم تؤذ أهلا ، ولم تفحش على جار\nتلوث بعد افتضال البرد مئزرها ، … لوثا ، على مثل دعص الرملة الهاري\nوالطيب يزداد طيبا أن يكون بها ، … في جيد واضحة الخدين معطار\nتسقي الضجيع - إذا استسقى - بذي أشر … عذب المذاقة بعد النوم مخمار\nكأن مشمولة صرفا بريقتها ، … من بعد رقدتها ، أو شهد مشتار\nأقول ، والنجم قد مالت أواخره … إلى المغيب : تثبت نظرة ، حار\nألمحة من سنا برق رأى بصري ، … أم وجه نعم بدا لي ، أم سنا نار ؟\nبل وجه نعم بدا ، والليل معتكر ، … فلاح من بين أثواب وأستار\nإن الحمول التي راحت مهجرة ، … يتبعن كل سيفه الرأي ، مغيار\nنواعم مثل بيضات بمحنية ، … يحفزن منه ظليما في نقا هار\nإذا تغنى الحمام الورق هيجني ، … وإن تغربت عنها أم عمار\nومهمة نازح ، تعوي الذئاب به ، … نائي المياه عن الوراد ، مقفار\nجاوزته بعلنداة مناقلة … وعر الطريق على الإحزان مضمار\nتجتاب أرضا إلى أرض بذي زجل … ماض على الهول هاد غير محيار\nإذا الركاب ونت عنها ركائبها ، … تشذرت ببعيد الفتر ، خطار\nكأنما الرحل منها فوق ذي جدد ، … ذب الرياد ، إلى الأشباح نظار\nمطرد ، أفردت عنه حلائله ، … من وحش وجرة أو من وحش ذي قار\nمجرس ، وحد ، جأب أطاع له … نبات غيث ، من الوسمي ، مبكار\nسراته ، ما خلا لبانه ، لهق ، … وفي القوائم مثل الوشم بالقار\nباتت له ليلة شهباء تسفعه … بحاصب ، ذات إشعان وأمطار\nوبات ضيفا لأرطاة ، وألجأه ، … مع الظلام ، إليها وابل سار\nحتى إذا ما انجلت ظلماء ليلته ، … واسفر الصبح عنه أي إسفار\nأهوى له قانص ، يسعى بأكلبه ، … عاري الأشاجع ، من قناص أنمار\nمحالف الصيد ، هباش ، له لحم ، … ما إن عليه ثياب غير أطمار\nيسعى بغضف براها ، فهي طاوية ، … طول ارتحال بها منه ، وتسيار\nحتى إذا الثور ، بعد النفر ، أمكنه ، … أشلى ، وأرسل غضفا ، كلها ضار\nفكر محمية من ان يفر ، كما … كر المحامي حفاظا ، خشية العار\nفشك بالروق منه صدر أولها ، … شك المشاعب أعشارا بأعشار\nثم انثنى ، بعد ، للثاني فأقصده … بذات ثغر بعيد القعر ، نعار\nوأثبت الثالث الباقي بنافذة ، … من باسيل عالم بالطعن ، كرار\nوظل ، في سبعة منها لحقن به ، … يكر بالروق فيها كر إسوار\nحتى إذا قضى منها لبانته ، … وعاد فيها بإقبال وإدبار\nانقض ، كالكوكب الدري ، منصلتا ، … يهوي ، ويخلط تقريبا بإحضار\nفذاك شبه قلوصى ، إذ أضر بها … طول السرى والسرى من بعد أسفار"},{"id":"diwan-nabigha:20","bookId":"diwan-nabigha","type":"poem","seq":20,"chapter":"البحر: بسيط تام","title":"لقد نهيت بني ذبيان عن أقر ،","page":"","text":"لقد نهيت بني ذبيان عن أقر ، … وعن تربعهم في كل أصفار\nوقلت : يا قوم ، إن الليث منقبض … على براثنه ، للوثبة الضاري\nلا أعرفن ربربا حورا مدامعها ، … كأن أبكارها نعاج دوار\nينظرن شزرا إلى من جاء عن عرض … بأوجه منكرات الرق ، أحرار\nخلف العضاريط لا يوقين فاحشة ، … مستمسكات بأقتاب وأكوار\nيذرين دمعا ، على الأشفار منحدرا ، … يأملن رحلة حصن وابن سيار\nإما عصيت ، فإني غير منفلت … مني اللصاب ، فجنبا حرة النار\nأو أضع البيت في سوداء مظلمة ، … تقيد العير ، لا يسري بها الساري\nتدافع الناس عنا ، حين نركبها ، … من المظالم تدعى أم صبار\nساق الرفيدات من جوش ومن عظم … وماش من رهط ربعي وحجار\nقرمي قضاعة حلا حول حجرته … مدا عليه بسلاف أنفار\nحتى استقل بجمع ، لا كفاء له ، … ينفي الوحوش عن الصحراء جرار\nلا يخفض الرز عن أرض ألم بها ؛ … ولا يضل على مصباحه الساري\nوعيرتني بنو ذبيان خشيته ، … وهل علي بأن أخشاك من عار ؟"},{"id":"diwan-nabigha:21","bookId":"diwan-nabigha","type":"poem","seq":21,"chapter":"البحر: وافر تام","title":"ألا من مبلغ عني خزيما ،","page":"","text":"ألا من مبلغ عني خزيما ، … وزبان ، الذي لم يرع صهري\nفإياكم وعورا داميات ، … كأن صلاءهن صلاء جمر\nفإني قد أتاني ما صنعتم ، … وما وشحتم من شعر بدر\nفلم يك نولكم أن تشفذوني ، … ودوني عازب وبلاد حجر\nفإن جوابها ، في كل يوم ، … ألم بأنفس منكم ، ووفر\nومن يتربص الحدثان تنزل … بمولاه عوان ، غير بكر"},{"id":"diwan-nabigha:22","bookId":"diwan-nabigha","type":"poem","seq":22,"chapter":"البحر: كامل تام","title":"نبئت زرعة ، والسفاهة كاسمها ،","page":"","text":"نبئت زرعة ، والسفاهة كاسمها ، … يهدي إلي غرائب الأشعار\nفحلفت ، يا زرع بن عمرو ، أنني … مما يشق ، على العدو ، ضراري\nأرأيت ، يوم عكاظ ، حين لقيتني … تحت العجاج ، فما شققت غباري\nإنا اقتسمنا خطتينا بيننا ، … فحملت برة ، واحتملت فجار\nفلتأتينك قصائد ، وليدفعن … جيش إليك قوادم الأكوار\nرهط ابن كوز أدراعهم ، … فيهم ، ورهط ربيعة بن حذار\nولرهط حراب وقد سورة … في المجد ، ليس غرابهم بمطار\nوبنو قعين ، لا محالة أنهم … آتوك ، غير مقلمي الأظفار\nسهكين من صدإ الحديد كأنهم ، … تحت السنور ، جنة البقار\nوبنو سواءة زائروك بوفدهم … جيشا ، يقودهم أبو المظفار\nوبنو جذيمة حي صدق ، سادة ، … غلبوا على خبت إلى تعشار\nمتكنفي جنبي عكاظ كليهما ، … وفرا ، غداة الروع والإنفار\nوالغاضريون ، الذين تحملوا ، … بلوائهم ، سيرا لدار قرار\nتمشي بهم أدم ، كأن رحالها … علق هريق على متون صوار\nشعب العلافيات بين فروجهم ، … والمحصنات عوازب الأطهار\nبرز الأكف من الخدام ، خوارج ، … من فرج كل وصيلة وإزار\nشمس ، موانع كل ليلة حرة ، … يخلفن ظن الفاحش المغيار\nجمعا ، يظل به الفضاء معضلا ، … يدع الإكام كأنهن صحاري\nلم يحرموا حسن الغذاء ، وأمهم … طفحت عليك بناتق مذكار\nحولي بنو دودان لا يعصونني ، … وبنو بغيض ، كلهم أنصاري\nزيد بن زيد حاضر بعراعر ، … وعلى كنيب مالك بن حمار\nوعلى الرميشة ، من سكين ، حاضر ؛ … وعلى الثينة من بني سيار\nفيهم بنات العسجدي ولاحق ، … ورقا مراكلها من المضمار\nيتحلب اليعضيد من أشداقها ، … صفرا مناخرها من الجرجار\nتشلى توابعها إلى ألافها ، … خبب السباع الوله ، الأبكار\nإت الرميشة مانع أرماحنا … ما كان من سحم بها ، وصفار\nفأصبن أبكارا ، وهن بإمة ، … أعجلنهن مظنة الإعذار"},{"id":"diwan-nabigha:23","bookId":"diwan-nabigha","type":"poem","seq":23,"chapter":"البحر: طويل","title":"كتمتك ليلا بالجمومين ساهرا ،","page":"","text":"كتمتك ليلا بالجمومين ساهرا ، … وهمين : هما مستكنا وظاهرا\nأحاديث نفس تشتكي ما يريبها ، … وورد هموم لم يجدن مصادرا\nتكلفني أن يفعل الدهر همها ، … وهل وجدت قبلي على الدهر قادرا ؟\nألم تر خير الناس أصبح نعشه … على فتية ، قد جاوز الحي ، سائرا\nونحن لديه ، نسأل الله خلده ، … يرد لنا ملكا ، وللأرض ، عامرا\nونحن نرجي الخلد إن فاز قدحنا ، … ونرهب قدح الموت إن جاء قامرا\nلك الخير إن وارت بك الأرض واحدا … واصبح جد الناس يظلع ، عاثرا\nوردت مطايا الراغبين ، وعريت … جيادك ، لا يحفي لها الدهر حافرا\nرأيتك ترعاني بعين بصيرة ، … وتبعث حراسا علي وناظرا\nوذلك من قول أتاك أقوله ، … ومن دس أعدائي إليك المآبرا\nفآليت لا آتيك ، إن جئت ، مجرما ، … ولا أبتغي جارا ، سواك ، مجاورا\nفأهلي فداء لامرىء ، إن أتيته … تقبل معروفي ، وسد المفاقرا\nسأكعم كلبي أن يربيك نبحه ، … وإن كنت أرعى مسحلان فحامرا\nوحلت بيوتي في يفاع ممنع ، … تخال به راعي الحمولة طائرا\nتزل الوعول العصم عن قذفاته ، … وتضحي ذراه ، بالسحاب ، كوافرا\nحذارا على أن لا تنال مقادتي ، … ولا نسوتي حتى يمتن حرائرا\nأقول ، وإن شطت بي الدار عنكم … غذا ما لقينا من معد مسافرا :\nألكني إلى النعمان حيث لقيته ، … فأهدى له الله الغيوث البواكرا\nوصصبحه فلج ولا زال كعبه ، … على كل من عادى من الناس ، ظاهرا\nورب عليه الله أحسن صنعه ، … وكان له ، على البرية ، ناصرا\nفألفيته يوما يبيد عدوه ، … وبحر عطاء ، يستخف المعابرا"},{"id":"diwan-nabigha:24","bookId":"diwan-nabigha","type":"poem","seq":24,"chapter":"البحر: طويل","title":"لقد قلت للنعمان ، يوم لقيته","page":"","text":"لقد قلت للنعمان ، يوم لقيته … يريد بني حن ، ببرقة صادر\nتجنب بني حن ، فإن لقاءهم … كريه ، وإن لم تلق إلا بصابر\nعظام اللهى ، أولاد عذرة إنهم … لهاميم ، يستلهونها بالحناجر\nوهم منعوا وادي القرى من عدوهم … بجمع مبير للعدو المكاثر\nمن الواردات الماء بالقاع تستقي … بأعجازها ، قبل استقاء الخناجر\nبزاخية ألوت بليف ، كأنه … عفاء قلاص ، طار عنها ، تواجر\nصغار النوى مكنوزة ليس قشرها ، … إذا طار قشر التمر ، عنها بطائر\nهم طردوا عنها بليا ، فأصبحت … بلي بواد ، من تهامة ، غائر\nوهم منعوها من قضاعة كلها ، … ومن مضر الحمراء ، عند التغاور\nوهم قتلوا الطائي بالحجر ، عنوة ، … أبا جابر ، واستنكحوا أم جابر"},{"id":"diwan-nabigha:25","bookId":"diwan-nabigha","type":"poem","seq":25,"chapter":"البحر: طويل","title":"ألا أبلغا ذبيان عني رسالة ،","page":"","text":"ألا أبلغا ذبيان عني رسالة ، … فقد أصبحت ، عن منهج الحق ، جائره\nأجدكم لن تزجروا عن ظلامة … سفيها ، ولن ترعوا لذي الود آصره\nفلو شهدت سهم وأبناء مالك ، … فتعذرني من مرة المتناصره\nلجاؤوا بجمع ، لم ير الناس مثله ، … تضاءل منه ، بالعشي ، قصائره\nليهنئ لكم أن قد نفيتم بيوتنا ، … مندى عبيدان المحلئ باقره\nوإني لألقى من ذوي الضغن منهم ، … وما أصبحت تشكو من الوجد ساهره\nكما لقيت ذات الصفا من حليفها ؛ … وما انفكت الأمثال في الناس سائره\nفقالت له : أدعوك للعقل ، وافيا ، … ولا تغسيني منك بالظلم بادره\nفلما توفي العقل ، إلا أقله ، … وجارت به نفس ، عن الحق جائره\nتذكر أني يجعل الله جنة ، … فيصبح ذا مال ، ويقتل واتره\nفلما رأى أن ثمر الله ماله ، … وأثل موجودا ، وسد مفاقره\nأكب على فأس يحد غرابها ، … مذكرة ، من المعاول ، باتره\nفقام لها من فوق جحر مشيد ، … ليقتلها ، أو تخطىء الكف بادره\nفلما وقاها الله ضربة فأسه ؛ … وللبر عين لا تغمض ناظره\nفقال : تعالي نجعل الله بيننا … على ما لنا ، أو تنجزي لي آخره\nفقالت : يمين الله أفعل ، إنني … رأيتك مسحورا ، يمينك فاجره\nأبى لي قبر ، لا يزال مقابلي ، … وضربة فأس ، فوق رأسي ، فاقره"},{"id":"diwan-nabigha:26","bookId":"diwan-nabigha","type":"poem","seq":26,"chapter":"البحر: بسيط تام","title":"ودع أمامة ، والتوديع تعذير ،","page":"","text":"ودع أمامة ، والتوديع تعذير ، … وما وداعك من قفت به العير\nوما رأيتك إلا نظرة عرضت ، … يوم النمارة ، والمأمور مأمور\nإن القفول إلى حي ، وإن بعدوا ، … أمسوا ، ودونهم ثهلان فالنير\nهل تبلغنيهم حرف مصرمة ، … أجد الفقار ، وإدلاج وتهجير\nقد عريت نصف حول أشهرا جددا … يسفي ، على رحلها ، بالحيرة ، المور\nوقارفت ، وهي لم تجرب ، وباع لها … من الفصافص ، بالنمي ، سفسير\nليست ترى حولها إلفا ، وراكبها … نشوان ، في جوة الباغوث ، مخمور\nتلقي الإوزين ، في أكناف دارتها ، … بيضا ، وبين يديها التبن منشور\nلولا الهمام الذي ترجى نوافله ، … لقال راكبها في عصبة : سيروا\nكأنها خاضب أظلافه ، لهق ، … قهد الإهاب ، تربته الزنابير\nأصاخ من نبأة ، أصغى لها أذنا ، … صماخها ، بدخيس الروق ، مستور\nمن حس أطلس ، تسعى تحته شرع … كأن أحناكها السفلى مآشير\nيقول راكبها الجني ، مرتفقا : … هذا لكن ، لحم الشاة محجور"},{"id":"diwan-nabigha:27","bookId":"diwan-nabigha","type":"poem","seq":27,"chapter":"قصائد","title":"صل صفا لا تنطوي من القصر ،","page":"","text":"صل صفا لا تنطوي من القصر ، … طويلة الإطراق من غير خفر\nداهية قد صغرت من الكبر ، … كأنما قد ذهبت بها الفكر\nمهروتة الشدقين ، حولاء النظر ، … تفتر عن عوج حداد ، كالإبر"},{"id":"diwan-nabigha:28","bookId":"diwan-nabigha","type":"poem","seq":28,"chapter":"البحر: بسيط تام","title":"يوما حليمة كانا من قديمهم ،","page":"","text":"يوما حليمة كانا من قديمهم ، … وعين باغ ، فكان الأمر ما ائتمرا\nيا قوم إن ابن هند غير تارككم ؛ … فلا تكونوا ، لأدنى وقعة ، جزرا"},{"id":"diwan-nabigha:29","bookId":"diwan-nabigha","type":"poem","seq":29,"chapter":"البحر: بسيط تام","title":"أخلاق مجدك جلت ، ما لها خطر ،","page":"","text":"أخلاق مجدك جلت ، ما لها خطر ، … في البأس والجود بين العلم والخبر\nمتوج بالمعالي ، فوق مفرقه ، … وفي الوغي ضيغم في صورة القمر"},{"id":"diwan-nabigha:30","bookId":"diwan-nabigha","type":"poem","seq":30,"chapter":"البحر: طويل","title":"بخالة ، أو ماء الذنابة أو سوى","page":"","text":"بخالة ، أو ماء الذنابة أو سوى … مظنة كلب ، أو مياه المواطر\nترى الراغبين العاكفين ببابه ، … على كل شيزى أترعت بالعراعر\nله بفناء البيت سوداء فخمة ، … تلقم أوصال الجزور العراعر\nبقية قدر من قدور تورثت … لآل الجلاح ، كابرا بعد كابر\nتظل الإماء يبتدرن قديمها ، … كما ابتدرت سعد مياه قراقر\nوهم ضربوا أنف الفزاري ، بعدما … أتاهم بمعقود من الأمر ، قاهر\nاتطمع في وادي القرى وجنابه ، … وقد منعوا منه جميع المعاشر ؟"},{"id":"diwan-nabigha:31","bookId":"diwan-nabigha","type":"poem","seq":31,"chapter":"البحر: كامل تام","title":"من مبلغ عمرو بن هند آية ،","page":"","text":"من مبلغ عمرو بن هند آية ، … ومن النصيحة كثرة الإنذار\nلاأعرفنك عارضا لرماحنا ، … في جف تغلب ، وادي الامرار\nيا لهف أمي ، بعد أسرة جعول ، … ألا ألاقيهم ورهط عرار"},{"id":"diwan-nabigha:32","bookId":"diwan-nabigha","type":"poem","seq":32,"chapter":"البحر: بسيط تام","title":"فإن يكون قد قضى ، من خله وطرا ،","page":"","text":"فإن يكون قد قضى ، من خله وطرا ، … فإنني منك لما أقض أوطاري\nيدني عليهن دفا ، ريشه هدم ، … وجؤجؤا ، عظمه ، من لحمه ، عار"},{"id":"diwan-nabigha:33","bookId":"diwan-nabigha","type":"poem","seq":33,"chapter":"البحر: مجزوء الكامل","title":"المرء يأمل أن يعيش ،","page":"","text":"المرء يأمل أن يعيش ، … وطول عيش قد يضره\nتفنى بشاشته ، ويبقى ، … بعد حلو العيش ، مره\nوتخونه الأيام ، حتى … لا يرى شيئا يسره\nكم شامت بي ، إن هلكت ، … وقائل : لله دره"},{"id":"diwan-nabigha:34","bookId":"diwan-nabigha","type":"poem","seq":34,"chapter":"البحر: طويل","title":"عفا ذو حسا من فرتنى ، فالفوارع ،","page":"","text":"عفا ذو حسا من فرتنى ، فالفوارع ، … فجنبا أريك ، فالتلاع الدوافع\nفمجتمع الأشراج غير رسمها … مصايف مرت ، بعدنا ، ومرابع\nتوهمت آيات لها ، فعرفتها … لستة أعوام ، وذا العام سابع\nرماد ككحل العين لأيا أبينه ، … ونؤي كجذم الحوض أثلم خاشع\nكأن مجر الرامسات ذيولها ، … عليه ، حصير ، نمقته الصوانع\nعلى ظهر مبناة جديد سيورها ، … يطوف بها ، وسط اللطيمة ، بائع\nفكفكفت مني عبرة ، فرددتها … على النحر ، منها مستهل ودامع\nعلى حين عاتبت المشيب على الصبا ، … وقلت : ألما أصح والشيب وازع ؟\nوقد حال هم ، دون ذلك ، شاغل … مكان الشغاف ، تبغيه الأصابع\nوعيد أبي قابوس ، في غير كنهه ، … أتاني ، ودوني راكس ، فالضواجع\nفبت كأني ساورتني ضيئلة … من الرقش ، في أنيابها السم ناقع\nيسهد ، من ليل التمام ، سليمها ، … لحلي النساء ، في يديه ، قعاقع\nتناذرها الراقون من سمها ، … تطلقه طورا ، وطورا تراجع\nأتاني ، أبيت اللعن ، أنك لمتني ، … وتلك التي تستك منها المسامع\nمقالة أن قد قلت : سوف أناله ، … وذلك ، من تلقاء مثلك ، رائع\nلعمري ، وما عمري علي بهين ، … لقد نطقت بطلا علي الأقارع\nأقارع عوف ، لا أحاول غيرها ، … وجوه قرود ، تبتغي من تجادع\nأتاك امرؤ مستبطن لي بغضة ، … له من عدو ، مثل ذلك ، شافع\nأتاك بقول هلهل النسج ، كاذب ، … ولم يأت بالحق ، الذي هو ناصع\nأتاك بقول لم أكن لأقوله ، … ولو كبلت في ساعدي الجوامع\nحلفت ، فلم أترك لنفسك ريبة ، … وهل يأثمن ذو أمة ، وهو طائع ؟\nبمصطحبات من لصاف وثيرة ، … يزرن إلالا ، سيرهن التدافع\nسماما تباري الريح ، خوصا عيونها ، … لهن رذايا ، بالطريق ، ودائع\nعليهن شعث عامدون لحجهم ، … فهن ، كأطراف الحني ، خواضع\nلكلفتني ذنب امرئ ، وتركته ، … كذي العر يكوى غيره ، وهو راتع\nفإن كنت ، لا ذو الضغن عني مكذب ، … ولا حلفي على البراءة نافع\nولا أنا مأمون بشيء أقوله ، … وأنت بأمر ، لا محالة ، واقع\nفإنك كالليل الذي هو مدركي ، … وإن خلت أن المنتأى عنك واسع\nخطاطيف حجن في جبال متينة ، … تمد بها أيد إليك نوازع\nأتوعد عبدا لم يخنك أمانة ، … وتترك عبدا ظالما ، وهو ظالع ؟\nوأنت ربيع ينعش الناس سيبه ، … وسيف ، أعيرته المنية ، قاطع\nأبى الله إلا عدله ووفاءه ، … فلا النكر معروف ولا العرف ضائع\nوتسقى ، إذا ما شئت ، غير مصرد ، … بزوراء ، في حافاتها المسك كانع"},{"id":"diwan-nabigha:35","bookId":"diwan-nabigha","type":"poem","seq":35,"chapter":"البحر: طويل","title":"ليهنئ بني ذبيان أن بلادهم","page":"","text":"ليهنئ بني ذبيان أن بلادهم … خلت لهم من كل مولى وتابع\nسوى أسد يحمونها كل شارق ، … بألفي كمي ذي سلاح ، ودارع\nقعودا على آل الوجيه ولاحق ، … يقيمون حولياتها بالمقارع\nيهزون أرماحا طوالا متونها ، … بأيد طوال ، عاريات الأشاجع\nفدع عنك قوما لا عتاب عليهم ، … هم ألحقوا عبسا بأرض القعاقع\nوقد عسرت ، من دونهم بأكفهم ، … بنو عامر عسر المخاض الموانع\nفما أنا في سهم ، ولا نصر مالك … ومولاهم عبد بن سعد ، بطامع\nإذا نزلوا ذا ضرغد ، فعتائدا ، … يغنيهم فيها نقيق الضفادع\nقعودا لدى أبياتهم يشمدونها ، … رمى الله في تلك الأنوف الكوانع"},{"id":"diwan-nabigha:36","bookId":"diwan-nabigha","type":"poem","seq":36,"chapter":"البحر: طويل","title":"وإن يرجع النعمان نفرح ونبتهج ،","page":"","text":"وإن يرجع النعمان نفرح ونبتهج ، … ويأت معدا ملكها وربيعها\nويرجع إلى غسان ، ملك وسؤدد ، … وتلك المنى ، لو أننا نستطيعها\nوإن يهلك النعمان تعر مطيه ، … ويلق ، إلى جنب الفناء ، قطوعها\nوتنحط حصان ، آخر الليل ، نحطة … تقضقض منها ، أو تكاد ضلوعها\nعلى إثر خير الناس ، إن كان هالكا ، … وإن كان في جنب الفتاة ضجيعها"},{"id":"diwan-nabigha:37","bookId":"diwan-nabigha","type":"poem","seq":37,"chapter":"البحر: كامل تام","title":"تعصي الإله ، وأنت تظهر حبه ،","page":"","text":"تعصي الإله ، وأنت تظهر حبه ، … هذا لعمرك ، في المقال ، بديع\nلو كنت تصدق حبه لأطعته ؛ … إن المحب ، لمن يحب ، مطيع"},{"id":"diwan-nabigha:38","bookId":"diwan-nabigha","type":"poem","seq":38,"chapter":"البحر: طويل","title":"دعاك الهوى ، واستجهلتك المنازل ،","page":"","text":"دعاك الهوى ، واستجهلتك المنازل ، … وكيف تصابي المرء ، والشيب شامل ؟\nوقفت بربع الدار ، قد غير البلى … معارفها ، والساريات الهواطل\nأسائل عن سعدى ، وقد مر بعدنا ، … على عرصات الدار ، سبع كوامل\nفسليت ما عندي بروحة عرمس ، … تخب برحلي ، تارة ، وتناقل\nموثقة الأنساء ، مضبورة القرا ، … نعوب ، إذا كل العتاق المراسل\nكأني شددت الرحل حين تشذرت ، … على قارح ، مما تضمن عاقل\nأقب ، كعقد الأندري ، مسحج ، … حزابية ، قد كدمته المساحل\nأضر بجرداء النسالة ، سمحج ، … يقبلها ، إذ أعوزته الحلائل\nإذا جاهدته الشد جد ، وإن ونت … تساقط لا وان ، ولا متخاذل\nوإن هبطا سهلا أثارا عجابة ؛ … وإن علوا حزنا تشظت جنادل\nورب بني البرشاء : ذهل وقيسها … وشيبان ، حيث استبهلتها المنازل\nلقد عالني ما سرها ، وتقطعت ، … لروعاتها ، مني القوى والوسائل\nفلا يهنىء الأعداء مصرع ملكهم ، … وما عشقت منه تميم ووائل\nوكانت لهم ربعية يحذرونها ، … إذا خضخضت ماء السماء القبائل\nيسير بها النعمان تغلي قدوره ، … تجيش بأسباب المنايا المراجل\nيحث الحداة ، جالزا بردائه ، … يقي حاجبيه ما تثير القنابل\nيقول رجال ، ينكرون خليقتي : … لعل زيادا ، لا أبا لك ، غافل\nأبى غفلتي أني ، إذا ما ذكرته ، … تحرك داء ، في فؤادي ، داخل\nوأن تلادي ، إن ذكرت ، وشكتي … ومهري ، وما ضمت لدي الأنامل\nحباؤك ، وو العيس العتاق كأنها … هجان المها ، تحدى عليها الرحائل\nفإن تك قد ودعت ، غير مذمم ، … أواسي ملك تبتتها الأوائل\nفلا تبعدن ، إن المنية موعد ؛ … وكل امرئ ، يوما ، به الحال زائل\nفما كان بين الخير لو جاء سالما ، … أبو حجر ، إلا ليال قلائل\nفإن تحي لا أملل حياتي ، وإن تمت ، … فما في حياتي ، بعد موتك ، طائل\nفآب مصلوه بعين جلية ، … وغودر الجولان ، حزم ونائل\nسقى الغيث قبرا بين بصرى وجاسم ، … بغيث ، من الوسمي ، قطر ووابل\nولا زال ريحان ومسك وعنبر … على منتهاه ، ديمة ثم هاطل\nوينبت حوذانا وعوفا منورا ، … سأتبعه من خير ما قال قائل\nبكى حارث الجولان من فقد ربه ، … وحوران منه موحش متضائل\nقعودا له غسان يرجون أوبه ، … وترك ، ورهط الأعجمين وكابل"},{"id":"diwan-nabigha:39","bookId":"diwan-nabigha","type":"poem","seq":39,"chapter":"البحر: طويل","title":"أهاجك ، من أسماء ، رسم المنازل ،","page":"","text":"أهاجك ، من أسماء ، رسم المنازل ، … بروضة نعمي ، فذات الأجاول\nأربت بها الأرواح ، حتى كأنما … تهادين ، أعلى تربها ، بالمناخل\nوكل ملث ، مكفهر سحابه ، … كميش التوالي ، مرثعن الأسافل\nإذا رجفت فيه رحى مرجحنة ، … تبعق ثجاج ، غزير الحوافل\nعهدت بها حيا كراما ، فبدلت … خناطيل آجال النعام الجوافل\nترى كل ذيال يعارض ربربا ، … على كل رجاف ، من الرمل ، هائل\nيثرن الحصى ، حتى يباشرن برده … غذا الشمس مجت ريقها بالكلاكل\nوناجية عديت في متن لاحب ، … كسحل اليماني ، قاصد للمناهل\nله خلج تهوي فرادى ، وترعوي … إلى كل ذي نيرين ، بادي الشواكل\nوإني عداني ، عن لقائك ، حادث ، … وهم ، أتى من دون همك ، شاغل\nنصحت بني عوف ، فلم يتقبلوا … وصاتي ؛ ولم تنجح لديهم وسائلي\nفقلت لهم : لا أعرفن عقائلا … رعابيب من جنبي أريك وعاقل\nضوارب بالأيدي ، وراء براغز ، … حسان ، كآرام الصريم الخواذل\nخلال المطايا يتصلن ، وقد أتت … قنان أبير ، دونها ، والكواثل\nوخلوا له ، بين الجناب وعالج ، … فراق الخليط ذي الذاة ، المزايل\nولا أعرفني بعدما قد نهيتكم ، … أجادل يوما في شوي وجامل\nوبيض غريرات ، تفيض دموعها ، … بمستكره ، يذرينه بالأنامل\nوقد خفت ، حتى ما تزيد مخافتي … على وعل ، في المطاوة ، عاقل\nمخافة عمرو أن تكون جياده … يقدن إلينا ، بين حاف وناعل\nإذا استعجلوها عن سجية مشيها ، … تتلع ، في أعناقها ، بالجحافل\nشوازب ، كالأجلام ، قد آل رمها ، … سماحيق صفرا في تليل وفائل\nويقذفن بالأولاد في كل منزل ، … تشحط في أسلائها ، كالوصائل\nترى عافيات الطير قد وثقت لها … بشبع من السخل العتاق الأكائل\nبرى وقع الصوان حد نسورها ، … فهن لطاف ، كالصعاد الذوابل\nمقرنة بالعيس والأدم كالقنا ، … عليها الخبور محقبات المراجل\nوكل صموت ، نثلة ، تبعية ، … ونسج سليم كل قضاء ذائل\nعلين بكديون ، وأبطن كرة ، … فهن وضاء ، صافيات القلائل\nعتاد امرئ لا ينقض البعد همه ، … طلوب الأعادي ، واضح ، غير خامل\nتحين بكفيه المنايا ، وتارة … تسحان سحا ، من عطاء ونائل\nإذا حل بالأرض البرية أصبحت … كئيبة وجه ، غبها غير طائل\nيؤم بربعي ، كأن زهاءه ، … إذا هبط الصحراء ، حرة راجل"},{"id":"diwan-nabigha:40","bookId":"diwan-nabigha","type":"poem","seq":40,"chapter":"البحر: وافر تام","title":"أمن ظلامة الدمن البوالي ،","page":"","text":"أمن ظلامة الدمن البوالي ، … بمرفض الحبي إلى وعال\nفأمواه الدنا ، فعويرضات ، … دوارس بعد أحياء حلال\nتأبد لا ترى إلا صوارا … بمرقوم ، عليه العهد ، خال\nتعاورها السواري والغوادي ، … وما تذري الرياح من الرمال\nأثيث نبته ، جعد ثراه ، … به عوذ المطافل والمتالي\nيكشفن الألاء ، مزينات ، … بغاب ردينة السحم ، الطوال\nكأن كشوحهن ، مبطنات … إلى فوق الكعوب ، برود خال\nفلما أن رأيت الدار قفرا ، … وخالف بال أهل الدار بالي\nنهضت إلى عذافرة صموت ، … مذكرة ، تجل عن الكلال\nفداء ، لامرئ سارت إليه … بعذرة ربها ، عمي وخالي\nومن يغرف ، من النعمان ، سجلا ، … فليس كمن يتيه في الضلال\nفإن كنت امرأ قد سؤت ظنا … بعبدك ، والخطوب إلى تبال\nفأرسل في بني ذبيان ، فاسأل ، … ولا تعجل إلي عن السؤال\nفلا عمر الذي أثني عليه ، … وما رفع الحجيج إلى إلال\nلما أغفلت شكرك ، فانتصحني ، … وكيف ، ومن عطاتك جل مالي\nولو كفي اليمين بغتك خونا ، … لأفردت اليمين من الشمال\nولكن لا تخان ، الدهر ، عندي ، … وعند الله تجزية الرجال\nله بحر يقمص بالعدولي ، … وبالخلج المحملة ، الثقال\nمضر بالقصور ، يذود عنها … قراقير النبيط إلى التلال\nوهوب للمخيسة النواجي ، … عليها القانئات من الرحال"},{"id":"diwan-nabigha:41","bookId":"diwan-nabigha","type":"poem","seq":41,"chapter":"البحر: وافر تام","title":"تخف الأرض ، إن تفقدك يوما ،","page":"","text":"تخف الأرض ، إن تفقدك يوما ، … وتبقى ما بقيت بها ثقيلا\nلأنك موضع القسطاس منها ، … فتمنع جانبيها أن تميلا"},{"id":"diwan-nabigha:42","bookId":"diwan-nabigha","type":"poem","seq":42,"chapter":"البحر: خفيف تام","title":"حدثوني بني الشقيقة ما يم","page":"","text":"حدثوني بني الشقيقة ما يم … يمنع فقعا ، بقرقر ، أن يزولا\nقبح الله ، ثم ثنى بلعن ، … وارث الجبان ، الجهولا\nمن يضر الأدنى ، ويعجز عن ضر … الأقاصي ، ومن يخون الخليلا\nيجمع الجيش ، ذا الألوف ، ويغزو … ثم لا يرزأ العدو فتيلا"},{"id":"diwan-nabigha:43","bookId":"diwan-nabigha","type":"poem","seq":43,"chapter":"البحر: بسيط تام","title":"ماذا رزئنا به من حية ذكر ،","page":"","text":"ماذا رزئنا به من حية ذكر ، … نضناضة بالرذايا ، صل أصلال\nلا يهنئ الناس ما يرعون من كلاء ، … وما يسوقون من أهل ومن مال\nبعد ابن عاتكة الثاوي على أبوى ، … أضحى ببلدة لا عم ولا خال\nسهل الخليفة ، مشاء بأقدمه ، … إلى ذوات الذرى ، حمال أثقال\nحسب الخليلين نأوي الأرض بينهما ، … هذا عليها ، وهذا تحتها بالي"},{"id":"diwan-nabigha:44","bookId":"diwan-nabigha","type":"poem","seq":44,"chapter":"البحر: بسيط تام","title":"بانت سعاد ، وأمسى حبلها انجذما ،","page":"","text":"بانت سعاد ، وأمسى حبلها انجذما ، … واحتلت الشرع فالأجزاع من إضما\nإحدى بلي ، وما هام الفؤاد بها ، … إلا السفاه ، وإلا ذكرة حلما\nليست من السود أعقابا إذا انصرفت ، … ولا تبيع ، بجنبي نخلة ، البرما\nغراء أكمل من يمشي على قدم … حسنا وأملح من حاورته الكلما\nقالت : أراك أخا رحل وراحلة ، … تغشى متالف ، لن ينظرنك الهرما\nحياك ربي ، فإنا لا يحل لنا … لهو النساء ، وإن الدين قد عزما\nمشمرين على خوص مزممة ، … نرجو الإله ، ونرجو البر والطعما\nهلا سألت بني ذبيان ما حسبي ، … إذا الدخان تغشى الأشمط البرما\nوهبت الريح من تلقاء ذي أرل ، … تزجي مع الليل من صرادها صرما\nصهب الظلال أتين التين عن عرض … يزجين غيما قليلا ماؤه شبما\nينبئك ذو عرضهم عني وعالمهم ، … وليس جاهل شيء مثل من علما\nإني أتمم أيساري ، وأمنحهم … مثنى الأيادي ، وأكسو الجفنة الأدما\nواقطع الخرق بالخرقاء ، قد جعلت ، … بعد الكلال ، تشكى الأين والسأما\nكادت تساقطني رحلي وميثرتي … بذي المجاز ، ولم تحسس به نعما\nمن قول حرمية قالت وقد ظعنوا : … هل في مخفيكم من يشتري أدما\nقلت لها ، وهي تسعى تحتض لبتها : … لا تحطمنك ؛ إن البيع قد زرما\nباتت ثلاث ليال ، ثم واحدة ، … بذي المجاز ، تراعي منزلا زيما\nفانشق عنها عمود الصبح ، جافلة ، … عدو الحوص تخاف القانص اللحما\nتحيد عن أستن ، سود أسافله ، … مشي الإماء الغوادي تحمل الحزما\nأو ذو وشوم بحوضي بات منكرسا ، … في ليلة من جمادى أخضلت ديما\nبات بحقف من البقار ، يحفزه ، … إذا استكف قليلا ، تربه انهدما\nمولي الريح روقيه وجبهته ، … كالهبرقي تنحى ينفخ الفحما\nحتى غدا مثل نصل السيف منصلتا ، … يقرو الأماعز من لبنان والأكما"},{"id":"diwan-nabigha:45","bookId":"diwan-nabigha","type":"poem","seq":45,"chapter":"البحر: بسيط تام","title":"قالت بنو عامر : خالوا بني اسد ،","page":"","text":"قالت بنو عامر : خالوا بني اسد ، … يا بؤس للجهل ، ضرارا لأقوام\nيأبى البلاء ، فلا نبغي بهم بدلا ، … ولا نريد خلاء بعد إحكام\nفصالحونا جميعا ، إن بدا لكم ، … ولا تقولوا لنا أمثالها ، عام\nإني لأخشى عليكم أن يكون لكم ، … من أجل بغضائهم ، يوم كأيام\nتبدو كواكبه ، والشمس طالعة ، … لا النور نور ، ولالإظلام إظلام\nأو تزجروا مكفهرا لا كفاء له ، … كالليل يخلط أصراما بأصرام\nمستحقبي حلق الماذي ، يقدمهم … سشم العرانين ، ضرابون للهام\nلهم لواء بكفي ماجد بطل ، … لا يقطع الخرق إلا طرفه سام\nيهدي كتائب خضرا ، ليس يعصمها … إلا ابتدار ، إلى موت ، بإللجام\nكم غادرت خيلنا منكم ، بمعترك ، … للخامعات ، أكفا بعد أقدام\nيا رب ذات خليل قد فجعن به ، … ومؤتمين ، وكانوا غير أيتام\nوالخيل تعلم أنا ، في تجاولها … عند الطعان ، أولو بؤسى وإنعام\nولوا ، وكبشهم يكبو لجبهته ، … عند الكماة صريعا ، جوفه دام"},{"id":"diwan-nabigha:46","bookId":"diwan-nabigha","type":"poem","seq":46,"chapter":"البحر: بسيط تام","title":"لا يبعد الله جيرانا ، تركتهم","page":"","text":"لا يبعد الله جيرانا ، تركتهم … مثل المصابيح ، تجلو ليلة الظلم\nلا يبرمون ، إذا ما الأفق جلله … برد الشتاء ، من الإمحال ، كالأدم\nهم الملوك وأبناء الملوك لهم … فضل على الناس ، في اللأواء والنعم\nأحلام عاد ، وأجساد مطهرة … من المعقة والآفات والإثم"},{"id":"diwan-nabigha:47","bookId":"diwan-nabigha","type":"poem","seq":47,"chapter":"البحر: كامل تام","title":"جمع محاشك يا يزيد ، فإنني","page":"","text":"جمع محاشك يا يزيد ، فإنني … أعددت يربوعا لكم وتميما\nولحقت بالنسب الذي عيرتني ، … وتركت أصلك ، يا يزيد ، ذميما\nعيرتني نسب الكرام ، وإنما … فخر المفاخر إن يعد كريما\nحدبت عل بطون ضنة كلها ، … إن ظالما فيهم ، وإن مظلوما\nلولا بنو عوف بن بهثة أصبحت ، … بالنعف ، أم بني أبيك عقيما"},{"id":"diwan-nabigha:48","bookId":"diwan-nabigha","type":"poem","seq":48,"chapter":"البحر: طويل","title":"أبلغ بني ذبيان أن لا أخا لهم","page":"","text":"أبلغ بني ذبيان أن لا أخا لهم … بعبس إذا حلوا الدماخ فأظلما\nبجمع ، كلون الأعبل الجون لونه ، … ترى ، في نواحيه ، زهيرا وحذيما\nهم يردون الموت ، عند لقائه ، … إذا كان ورد الموت ، لا بد ، أكرما"},{"id":"diwan-nabigha:49","bookId":"diwan-nabigha","type":"poem","seq":49,"chapter":"البحر: وافر تام","title":"ألم أقسم عليك لتخبرني ،","page":"","text":"ألم أقسم عليك لتخبرني ، … أمحمول ، على النعش ، الهمام\nفإني لا ألام على دخول ؛ … ولكن ما وارءك يا عصام ؟\nفإن يهلك أبو قابوس يهلك … ربيع الناس ، والشهر الحرام\nونمسك ، بعده ، بذناب عيش … أجب الظهر ، ليس له سنام"},{"id":"diwan-nabigha:50","bookId":"diwan-nabigha","type":"poem","seq":50,"chapter":"البحر: وافر تام","title":"أتاركة تدللها قطام ،","page":"","text":"أتاركة تدللها قطام ، … وضنا بالتحية والكلام\nفإن كان الدلال ، فلا تلجي ؛ … وإن كان الوداع ، فبالسلام\nفلو كانت ، غداة البين ، منت ، … وقد رفعوا الخدور على الخيام\nصفحت بنظرة ، فرأيت منها ، … تحيت الخدر ، واضعة القرام\nترائب يستضيء الحلي فيها ، … كجمر النار بذر بالظلام\nكأن الشذر والياقوت ، منها ، … على جيداء فاترة البغام\nخلت بغزالها ، ودنا عليها … أراك الجزع ، أسفل من سنام\nتسف بريره ، وترود فيه ، … إلى دبر النهار ، من البشام\nكأن مشعشعا من بصرى ، … نمته البخت ، مشدود الختام\nنمين قلاله من بيت راس … إلى لقمان ، في سوق مقام\nغذا فضت خواتمه علاه … يبيس القمحان ، من المدام\nعلى انيابها بغريض مزن ، … تقبله الجباه من الغمام\nفأضحت في مداهن باردات ، … بمنطلق الجنوب ، على الجهام\nتلذ لطعمه ، وتخال فيه ، … إذا نبهتها ، بعد المنام\nفدعها عنك ، إذ شطت نواها ، … ولجت ، من بعادك ، في غرام\nولكن ما أتاك عن ابن هند ، … من الحزم المبين ، والتمام\nفداء ، ما تقل النعل مني … إلى أعلى الذؤابة ، للهمام\nومغزاه قبائل غائظات ، … على الذهيوط ، في لجب لهام\nيقدن مع امرىء يدع الهوينا ، … ويعمد للمهمات العظام\nأعين على العدو ، بكل طرف ، … وسلهبة تجلل في السمام\nوأسمر مارن ، يلتاح ، فيه ، … سنان ، مثل نبراس النهام\nوأنبأه المنبىء أن حيا … حلولا من حرام ، أو جذام\nوأن القوم نصرهم جميع ، … فئام مجلبون إلى فئام\nفأوردهن بطن الأتم ، شعثا ، … يصن المشي كالحدإ التوام\nعلى إثر الأدلة والبغايا ، … وخفق الناجيات من الشآم\nفباتوا ساكنين ، وبات يسري ، … يقربهم له ليل التمام\nفصبحهم بها صهباء صرفا ، … كأن رؤوسهم بيض النعام\nفذاق الموت من بركت عليه ، … وبالناجين أظفار دوام\nوهن ، كأنهن نعاج رمل ، … يسوين الذيول على الخدام\nيوصين الرواة ، إذا ألموا ، … بشعث مكرهين على الفطام\nوأضحى ساطعا بجبال حمسى ، … دقاق الترب ، مختزم القتام\nفهم الطالبون ليدركوه ، … وما راموا بذلك من مرام\nإلى صعب المقادة ، ذي شريس ، … نماه ، في فروع المجد ، نام\nأبوه قبله ، وأبو أبيه ، … بنوا مجد الحياة على إمام\nفدوخت العراق ، فكل قصر … يجلل خندق منه ، وحام\nوما تنفك محلولا عراها ، … على متناذر الأكلاء ، طام"},{"id":"diwan-nabigha:51","bookId":"diwan-nabigha","type":"poem","seq":51,"chapter":"البحر: كامل تام","title":"طلعوا عليك براية معروفة","page":"","text":"طلعوا عليك براية معروفة … يوم الأبيس ، إذ لقيت لئيما\nقوم تدارك ، بالعقيرة ، ركضهم … أولاد زردة ، إذ تركت ذميما"},{"id":"diwan-nabigha:52","bookId":"diwan-nabigha","type":"poem","seq":52,"chapter":"البحر: وافر تام","title":"ولست بذاخر لغد طعاما ،","page":"","text":"ولست بذاخر لغد طعاما ، … حذار غد ، لكل غد طعام\nتمحضت المنون له بيوم … أتى ، ولكل حاملة تمام"},{"id":"diwan-nabigha:53","bookId":"diwan-nabigha","type":"poem","seq":53,"chapter":"البحر: سريع","title":"هذا غلام حسن وجهه ،","page":"","text":"هذا غلام حسن وجهه ، … مستقبل الخير ، سريع التمام\nللحارث الأكبر ، والحارث … الأصغر ، والأعرج خير الأنام\nثم لهند ، ولهند ، وقد … أسرع ، في الخيرات ، منه إمام\nخمسة آبائهم ، ما هم ؟ … هم خير من يشرب صوب الغمام"},{"id":"diwan-nabigha:54","bookId":"diwan-nabigha","type":"poem","seq":54,"chapter":"البحر: وافر تام","title":"ألا أبلغ ، لديك ، أبا حريث ؛","page":"","text":"ألا أبلغ ، لديك ، أبا حريث ؛ … وعاقبة الملامة للمليم\nفكيف ترى معاقبتي وسعيي … بأذواد القيصمة ، والقصيم\nفنمت الليل ، إذ أوقعت فيكم ، … قبائل عامر وبني تميم\nوساغ لي الشارب ، وكنت قبلا ، … أكاد أغص بالماء الحميم"},{"id":"diwan-nabigha:55","bookId":"diwan-nabigha","type":"poem","seq":55,"chapter":"البحر: رجز تام","title":"نفس عصام سودت عصاما ،","page":"","text":"نفس عصام سودت عصاما ، … وعلمته الكر والإقداما\nوصيرته ملكا هماما ، … حتى علا ، وجاوز الأقواما"},{"id":"diwan-nabigha:56","bookId":"diwan-nabigha","type":"poem","seq":56,"chapter":"البحر: وافر تام","title":"لعمرك ، ما خشيت على يزيد ،","page":"","text":"لعمرك ، ما خشيت على يزيد ، … من الفخر المضلل ، ما أتاني\nكأن التاج ، معصوبا عليه ، … لأذواد أصبن بذي أبان\nفحسبك أن تهاض بمحكمات … يمر بها الروي على لساني\nفقبلك ما شتمت وقاذ عوني ، … فما نزر الكلام ولا شجاني\nيصد الشاعر الثنيان عني ، … صدود البكر عن قرم هجان\nأثرت الغي ، ثم نزعت عنه ، … كما حاد الأزب عن الظعان\nفإن يقدر عليك أبو قبيس ، … تمط بك المعيشة في هوان\nوتخضب لحية ، غدرت وخانت ، … بأحمر ، من نجيع الجوف ، آني\nوكنت أمينة ، لو لم تخنه ، … ولكن لا أمانة لليمان"},{"id":"diwan-nabigha:57","bookId":"diwan-nabigha","type":"poem","seq":57,"chapter":"البحر: وافر تام","title":"فإن يقدر علي أبو قبيس ،","page":"","text":"فإن يقدر علي أبو قبيس ، … تجدني ، عنده ، حسن المكان\nتجدني كنت خيرا منك غيبا ، … وأمضى باللسان وبالسنان\nوأي الناس أغدر من شآم ، … له صردان ، منطلق اللسان\nفإن الغدر ، قد علمت معد ، … بناه ، في بني ذبيان ، باني\nوإن الفحل تنزع خصيتاه ، … فيصبح جافرا قرح العجان"},{"id":"diwan-nabigha:58","bookId":"diwan-nabigha","type":"poem","seq":58,"chapter":"البحر: وافر تام","title":"غشيت منازلا بعريتنات ،","page":"","text":"غشيت منازلا بعريتنات ، … فأعلى الجزع للحي المبن\nتعاورهن صرف الدهر ، حتى … عفون ، وكل منهمر مرن\nوقفت بها القلوض ، على اكتئاب ، … وذاك تفارط الشوق المعني\nأسائلها ، وقد سفحت دموعي ، … كأن مفيضهن غروب شن\nبكاء حمامة ، تدعو هديلا ، … مفجعة ، على فنن ، تغني\nالكني يا عيين إليك قولا … سأهديه إليك ، إليك عني\nقوافي كالسلام ، إذا استمرت ، … فليس يرد مذهبها التظني\nبهن أدين من يبغي أذاني ، … مداينة المداين ، فليدنيب\nأتخذل ناصري وتعز عبسا ، … أيربوع بن غيظ للمعن\nكأنك من جمال بني أقيش ، … يقعقع ، خلف رجليه ، بشن\nتكون نعامة طورا ، وطورا … هوي الريح ، تنسج كل فن\nتمن بعادهم ، واستبق منهم ، … فإنك سوف تترك والتمني\nلدى جرعاء ، ليس بها أنيس ؛ … وليس بها الدليل بمطمئن\nإذا حاولت ، في أسد ، فجورا ، … فإني لست منك ، ولست مني\nفهم درعي ، التي استلأمت فيها ، … إلى يوم النسار ، وهم مجني\nوهم وردوا الجفار على تميم ؛ … وهم أصحاب يوم عكاظ ، إني\nشهدت لهم مواطن صادقات ، … أتينهم بود الصدر مني\nوهم ساروا لحجر في خميس ، … وكانوا ، يوم ذلك ، عند ظني\nوهم زحفوا ، لغسان ، بزحف … رحيب السرب ، أرعن ، مرجحن\nبكل مجرب ، كالليث يسمو … على أوصال ذيال ، رفن\nوضمر كالقداح ، مسومات ، … عليها معشر أشباه جن\nغداة تعاورته ، ثم ، بيض ، … دفعن إليه في الرهج المكن\nولو أني أطعتك في أمور ، … قرعت ندامة ، من ذاك ، سني"},{"id":"diwan-nabigha:59","bookId":"diwan-nabigha","type":"poem","seq":59,"chapter":"البحر: وافر تام","title":"وأعيار صوادر عن حماتا ،","page":"","text":"وأعيار صوادر عن حماتا ، … لبين الكفر والبرق الدواني\nألا زعمت بنو عبس بأني ، … ألا كذبوا ، كبير السن فان"},{"id":"diwan-nabigha:60","bookId":"diwan-nabigha","type":"poem","seq":60,"chapter":"البحر: وافر تام","title":"نات بسعاد عنك نوى شطون ،","page":"","text":"نات بسعاد عنك نوى شطون ، … فبانت ، والفؤاد بها رهين\nوحلت في بني القين بن جسر ، … فقد نبغت لنا ، منهم ، شؤون\nتأوبني ، بعملة ، اللواتي … منعن النوم ، إذ هدأت عيون\nكأن الرحل شد به خذوف ، … من الجونات ، هادية عنون\nمن المستعرضات بعين نخل ، … كأن بياض لبته سدين\nكقوس الماسخي ، أرن فيها ، … من الشرعي ، مربوع متين\nإلى ابن محرق أعملت نفسي ، … وراحلتي ، وقد هدت العيون\nاتيتك عاريا خلقا ثيابي ، … على خوف ، تظن بي الظنون\nفألفيت الأمانة لم تخنها ؛ … كذلك كان نوح لا يخون"},{"id":"diwan-nabigha:61","bookId":"diwan-nabigha","type":"poem","seq":61,"chapter":"البحر: طويل","title":"فتى ، تم فيه ما يسر صديقه ؛","page":"","text":"فتى ، تم فيه ما يسر صديقه ؛ … على أن فيه ما يسيء المعاديا\nفتى ، كملت أخلاقه ، غير أنه … جواد ، فما يبقي على المال باقيا"},{"id":"diwan-nabigha:62","bookId":"diwan-nabigha","type":"poem","seq":62,"chapter":"البحر: رمل تام","title":"سألتني عن أناس هلكوا ،","page":"","text":"سألتني عن أناس هلكوا ، … أكل الدهر عليهم وشرب"},{"id":"diwan-nabigha:63","bookId":"diwan-nabigha","type":"poem","seq":63,"chapter":"البحر: متقارب تام","title":"بعاري النواهق ، صلت الجبين ،","page":"","text":"بعاري النواهق ، صلت الجبين ، … يستن كالتيس في الحلب"},{"id":"diwan-nabigha:64","bookId":"diwan-nabigha","type":"poem","seq":64,"chapter":"البحر: طويل","title":"متى تأته ، تعشو إلى ضوء ناره ،","page":"","text":"متى تأته ، تعشو إلى ضوء ناره ، … تجد خير نار ، عندها خير موقد"},{"id":"diwan-nabigha:65","bookId":"diwan-nabigha","type":"poem","seq":65,"chapter":"البحر: وافر تام","title":"فأضحت بعدما وصلت بدار","page":"","text":"فأضحت بعدما وصلت بدار … شطون ، لا تعاد ولا تعود"},{"id":"diwan-nabigha:66","bookId":"diwan-nabigha","type":"poem","seq":66,"chapter":"البحر: طويل","title":"حباء شقيق فوق أحجار قبره ،","page":"","text":"حباء شقيق فوق أحجار قبره ، … وما كان يحبى ، قبله ، قبر وافد"},{"id":"diwan-nabigha:67","bookId":"diwan-nabigha","type":"poem","seq":67,"chapter":"البحر: كامل تام","title":"بالدر والياقوت زين نحرها ،","page":"","text":"بالدر والياقوت زين نحرها ، … ومفصل من لؤلؤ وزبرجد"},{"id":"diwan-nabigha:68","bookId":"diwan-nabigha","type":"poem","seq":68,"chapter":"البحر: طويل","title":"إذا تلقهم لا تلق للبيت عورة ،","page":"","text":"إذا تلقهم لا تلق للبيت عورة ، … ولا الجار محروما ، ولا الأمر ضائعا"},{"id":"diwan-nabigha:69","bookId":"diwan-nabigha","type":"poem","seq":69,"chapter":"البحر: بسيط تام","title":"صبرا بغيض بن ريث ، إنها رحم ،","page":"","text":"صبرا بغيض بن ريث ، إنها رحم ، … حبتم بها فأناختكم بجعجاع"},{"id":"diwan-nabigha:70","bookId":"diwan-nabigha","type":"poem","seq":70,"chapter":"البحر: بسيط تام","title":"يا مانع الضيم أن يغشى سراتهم ،","page":"","text":"يا مانع الضيم أن يغشى سراتهم ، … وحامل الإصر عنهم ، بعدما غرقوا"},{"id":"diwan-nabigha:71","bookId":"diwan-nabigha","type":"poem","seq":71,"chapter":"البحر: طويل","title":"إذا غضبت لم يشعر الحي أنها","page":"","text":"إذا غضبت لم يشعر الحي أنها … غضوب ، وإن نالت رضى لم تزهزق"},{"id":"diwan-nabigha:72","bookId":"diwan-nabigha","type":"poem","seq":72,"chapter":"البحر: طويل","title":"وعريت من مال وخير جمعته ،","page":"","text":"وعريت من مال وخير جمعته ، … كما عريت ، مما تمر ، المغازل"},{"id":"diwan-nabigha:73","bookId":"diwan-nabigha","type":"poem","seq":73,"chapter":"البحر: سريع","title":"الطاعن الطعنة ، يوم الوغى ،","page":"","text":"الطاعن الطعنة ، يوم الوغى ، … ينهل منها الأسل الناهل"},{"id":"diwan-nabigha:74","bookId":"diwan-nabigha","type":"poem","seq":74,"chapter":"البحر: طويل","title":"جزى ربه عني عدي بن حاتم ،","page":"","text":"جزى ربه عني عدي بن حاتم ، … جزاء الكلاب العاويات ، وقد فعل\nظللنا ببرقاء اللهيم ، تلفنا … قبول نكاد من ظلالتها نمسي\nإذا أنا لم أنفع خليلي بوده ، … فإن عدوي لا يضرهم بغضي"},{"id":"diwan-nabigha:75","bookId":"diwan-nabigha","type":"poem","seq":75,"chapter":"البحر: بسيط تام","title":"خيل صيام ، وخيل غير صائمة ،","page":"","text":"خيل صيام ، وخيل غير صائمة ، … تحت العجاج ، وأخرى تعلك اللجما"},{"id":"diwan-nabigha:76","bookId":"diwan-nabigha","type":"poem","seq":76,"chapter":"البحر: سريع","title":"ألمم برسم الطلل الأقدم ،","page":"","text":"ألمم برسم الطلل الأقدم ، … بجانب السكران ، فالأيهم"},{"id":"diwan-nabigha:77","bookId":"diwan-nabigha","type":"poem","seq":77,"chapter":"البحر: طويل","title":"تعدو الذئاب على من لا كلاب له ،","page":"","text":"تعدو الذئاب على من لا كلاب له ، … وتتقي مربض المستنفر الحامي\nفلن أذكر النعمان إلا بصالح ، … فإن له عندي يديا وأنعما"}]};